-- Trim the sample billings to Jan-Jul (today is July 2026 — no point
-- showing "future" fabricated months), and replace the old disconnected
-- 8-entry send-out fixture with a linked dataset: one pipeline_entry per
-- remaining billing, same candidate/company/team, staged sent -> interview
-- -> offer -> placed and closing on the billing's date. Send-Outs, Billings,
-- Report, and Leaderboard now all tell the same story. Safe to delete/edit
-- from the app.

DELETE FROM billings WHERE id LIKE 'smpl-2026-b-%' AND date::date > '2026-07-31';

DELETE FROM pipeline_entries WHERE id IN (
  'smpl-so-1', 'smpl-so-2', 'smpl-so-3', 'smpl-so-4', 'smpl-so-5', 'smpl-so-6', 'smpl-so-7', 'smpl-so-8'
);

ON CONFLICT (id) DO NOTHING;
